v1''::text))","CHECK (((timeout_ms >= 1000) AND (timeout_ms <= 60000)))"]}}'::jsonb;
 for r in select unnest(names) name loop
  if to_regclass(r.name) is null then return false;end if;
  select jsonb_build_object('columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=r.name::regclass and a.attnum>0 and not a.attisdropped),
   'constraints',(select jsonb_agg(pg_get_constraintdef(k.oid) order by k.conname) from pg_constraint k where k.conrelid=r.name::regclass)) into actual;
  if actual is distinct from expected->r.name then return false;end if;
